package io.knowledgebrain.activity;
import java.util.*;import java.time.Duration;import java.nio.charset.StandardCharsets;
import org.apache.kafka.clients.consumer.*;import org.apache.kafka.common.*;import org.apache.kafka.common.errors.WakeupException;import org.springframework.context.SmartLifecycle;import io.micrometer.core.instrument.MeterRegistry;import org.slf4j.LoggerFactory;
final class ActivityConsumer implements SmartLifecycle {
 private final ActivityStore store;private final ActivityClickHouse index;private final ActivitySnapshot source;private final Properties options;private final MeterRegistry metrics;private volatile KafkaConsumer<String,byte[]> client;private volatile Thread consumer,projector;private volatile boolean running,joined;
 ActivityConsumer(ActivityStore store,ActivityClickHouse index,ActivitySnapshot source,Properties options,MeterRegistry metrics){this.store=store;this.index=index;this.source=source;this.options=options;this.metrics=metrics;}
 static boolean gap(Long committed,long first,long end){return first<0||end<first||committed==null&&first>0||committed!=null&&(committed<first||committed>end);}
 static void recover(Consumer<String,byte[]> client,Collection<TopicPartition> assigned,Map<TopicPartition,Long> capturedEnd,Runnable backfill){backfill.run();var committed=new HashMap<TopicPartition,OffsetAndMetadata>();for(var p:assigned){long end=capturedEnd.get(p);client.seek(p,end);committed.put(p,new OffsetAndMetadata(end));}client.commitSync(committed);}
 public void start(){if(running)return;running=true;consumer=Thread.ofVirtual().name("activity-kafka").start(this::consume);projector=Thread.ofVirtual().name("activity-clickhouse").start(this::project);}
 private void consume(){while(running){try(var c=new KafkaConsumer<String,byte[]>(options)){client=c;joined=false;c.subscribe(ActivityEvent.topics(),new ConsumerRebalanceListener(){public void onPartitionsRevoked(Collection<TopicPartition> p){joined=false;}public void onPartitionsAssigned(Collection<TopicPartition> p){var committed=c.committed(Set.copyOf(p));var first=c.beginningOffsets(p);var end=c.endOffsets(p);boolean recovery=!store.state().seeded();for(var partition:p){var offset=committed.get(partition);recovery|=gap(offset==null?null:offset.offset(),first.get(partition),end.get(partition));}if(recovery){recover(c,p,end,()->source.backfill(store));metrics.counter("brain.activity.recovery","outcome","canonical").increment();}else for(var partition:p){var offset=committed.get(partition);c.seek(partition,offset==null?first.get(partition):offset.offset());}joined=true;}});while(running){var records=c.poll(Duration.ofSeconds(1));for(var record:records){var headers=new HashMap<String,String>();for(var h:record.headers())if(h.value()==null||headers.putIfAbsent(h.key(),new String(h.value(),StandardCharsets.UTF_8))!=null)throw ActivityEvent.invalid();ActivityEvent.transport(record.topic(),record.value(),record.key(),headers);store.stage(record.topic(),record.value());c.commitSync(Map.of(new TopicPartition(record.topic(),record.partition()),new OffsetAndMetadata(record.offset()+1)));metrics.counter("brain.activity.events","kind",ActivityEvent.decode(record.topic(),record.value()).kind()).increment();LoggerFactory.getLogger(getClass()).info("activity_inbox event_id={} trace_id={} outcome=STAGED",headers.get("id"),headers.get("trace_id"));}}}catch(WakeupException e){if(!running)break;}catch(RuntimeException e){metrics.counter("brain.activity.failures","operation","consume").increment();LoggerFactory.getLogger(getClass()).warn("activity_consume retry failure={}; no failed record acknowledged",e.getClass().getSimpleName());}finally{client=null;joined=false;}pause();}}
 private void project(){while(running){try{var state=store.state();if(!state.rebuilding()){var rows=store.pending(100);if(!rows.isEmpty()){index.applyAll(rows.stream().map(store::decode).toList());store.appliedAll(rows.stream().map(ActivityStore.Pending::eventId).toList());metrics.counter("brain.activity.projection","outcome","applied").increment(rows.size());}if(state.seeded()&&!state.ready())store.finishIfDrained();}}catch(RuntimeException e){metrics.counter("brain.activity.failures","operation","project").increment();LoggerFactory.getLogger(getClass()).warn("activity_project retry failure={}; durable rows remain pending",e.getClass().getSimpleName());}pause();}}
 private void pause(){if(running)try{Thread.sleep(500);}catch(InterruptedException e){Thread.currentThread().interrupt();running=false;}}
 boolean ready(){return running&&joined&&store.state().ready()&&!store.state().rebuilding();}
 public boolean isRunning(){return running;}public void stop(){running=false;var c=client;if(c!=null)c.wakeup();for(var t:new Thread[]{consumer,projector})if(t!=null)try{t.join(15000);}catch(InterruptedException e){Thread.currentThread().interrupt();}}
}
